<section class="page"><h1>Hisoblar va rollar</h1><p class="muted">Administrator o‘z rolini o‘zgartira olmaydi. Barcha tekshiruvlar serverda bajariladi.</p><div class="stack"><?php foreach($items as $x):?><article class="panel attachment"><div><h2><?=e($x['name'])?></h2><p class="muted"><?=e($x['email'])?> · <?=e($x['role'])?></p></div><?php if($x['id']!=$user['id']):?><form class="actions" method="post" action="<?=url('user-role')?>"><?=csrf()?><input type="hidden" name="id" value="<?=$x['id']?>"><select name="role" aria-label="<?=e($x['name'])?> roli"><?php foreach(['user','moderator','admin']as $r):?><option <?=$x['role']===$r?'selected':''?>><?=$r?></option><?php endforeach?></select><button class="secondary">Yangilash</button></form><?php endif?></article><?php endforeach?></div></section>
